// TypeScript Version: 4.1

/**
* Converts a symbol alias or shorthand to a canonical symbol alias.
*
* ## Notes
*
* -   For symbols having more than one accepted alias (e.g., `cross` and `plus`), the function returns the canonical alias.
* -   If unable to resolve an alias, the function returns `null`.
*
* @param value - symbol alias or shorthand
* @returns canonical symbol alias
*
* @example
* var v = symbol2alias( 'o' );
* // returns 'circle'
*
* v = symbol2alias( 'plus' );
* // returns 'cross'
*
* v = symbol2alias( 'beep' );
* // returns null
*/
declare function symbol2alias( value: string ): string | null;


// EXPORTS //

export = symbol2alias;
